/* Vetora iteration 02: public, local prototype. No booking/authentication API calls. */
(() => {
'use strict';
const {clinics,doctors}=window.VETORA_DATA;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=path=>window.VETORA_EMBEDDED_ASSETS?.[path]||path;
const normalize=s=>String(s||'').toLocaleLowerCase('ru').replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',down:'<path d="m6 9 6 6 6-6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',external:'<path d="M14 4h6v6M20 4l-9 9"/><path d="M10 4H5a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',plus:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const svg=(id,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.arrow}</svg>`;
const image=(i,cls='')=>`<img class="${cls}" src="${asset(`assets/original-${i}.${i===3?'webp':i>=14&&i!==17?'jpg':'png'}`)}" alt="" aria-hidden="true">`;
const categoryList=[['therapy','Терапия',6],['surgery','Хирургия',11],['diagnostic','УЗИ и диагностика',9],['dental','Стоматология',10],['dermatology','Дерматология',4],['cardiology','Кардиология',6],['vaccination','Вакцинация',8],['ophthalmology','Офтальмология',5],['neurology','Неврология',9],['oncology','Онкология',4],['orthopedics','Травматология',11],['all','Все направления',12]];
const catName=id=>categoryList.find(x=>x[0]===id)?.[1]||'Все направления';
const areas=[['all','Москва, все районы'],['center','Центр Москвы'],['nw','Северо-запад Москвы'],['west','Запад Москвы'],['se','Юго-восток Москвы'],['south','Юг Москвы'],['mo','Московская область']];
const state={page:'home',q:'',category:'all',area:'all',network:'all',sort:'default',service:'',clinic:'',region:'all',homeLimit:6,mapClinic:'',demoSession:false};
let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('vetora-v2-favorites')||'[]').filter(id=>clinics.some(c=>c.id===id)));}catch{}
let trigger=null, toastTimer, focusAfterRoute=null;
const navItems=[['home','Главная',1],['clinics','Клиники',2],['doctors','Врачи',5],['services','Услуги',4]];
const brand=()=>`<a class="brand" href="#home" aria-label="Vetora — главная">${image(0)}<span>Vetora</span></a>`;
function route(page,changes={}){const next={...state,...changes,page};const p=new URLSearchParams();for(const k of ['q','category','area','network','sort','service','clinic','region'])if(next[k]&&next[k]!==({category:'all',area:'all',network:'all',sort:'default',region:'all'}[k]||''))p.set(k,next[k]);const hash=page+(p.size?'?'+p:'');if(location.hash.slice(1)===hash){readRoute();}else location.hash=hash;}
function readRoute(){const [page,params='']=location.hash.slice(1).split('?');const p=new URLSearchParams(params);state.page=['home','clinics','doctors','services','clinic','favorites','map','about'].includes(page)?page:'home';for(const k of ['q','category','area','network','sort','service','clinic','region'])state[k]=p.get(k)||({category:'all',area:'all',network:'all',sort:'default',region:'all'}[k]||'');if(!['all','moscow','mo'].includes(state.region))state.region='all';if(!['all','Белый Клык','Свой Доктор'].includes(state.network))state.network='all';if(!['default','low','name'].includes(state.sort))state.sort='default';if(!categoryList.some(c=>c[0]===state.category))state.category='all';if(!areas.some(a=>a[0]===state.area))state.area='all';render();window.scrollTo(0,0);const focusTarget=focusAfterRoute&&$('#'+focusAfterRoute);(focusTarget||$('#main')).focus({preventScroll:true});focusAfterRoute=null;}
function renderHeader(){const active=state.page==='clinic'?'clinics':state.page;$('#header').innerHTML=`${brand()}<nav class="nav" aria-label="Основная навигация">${navItems.map(([id,label])=>`<a href="#${id}${state.region!=='all'?'?region='+encodeURIComponent(state.region):''}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="header-actions"><button class="location-button" data-action="region" aria-label="Выбрать регион: ${regionName()}">${svg('pin')}<span>${regionName()}</span>${svg('down')}</button><button class="btn white" data-action="${state.demoSession?'account':'login'}">${image(5)}${state.demoSession?'Кабинет':'Войти'}</button></div>`;document.querySelector('.mobile-nav')?.remove();document.body.insertAdjacentHTML('beforeend',`<nav class="mobile-nav" aria-label="Навигация на мобильном">${navItems.map(([id,label,i])=>`<a href="#${id}${state.region!=='all'?'?region='+encodeURIComponent(state.region):''}" ${active===id?'aria-current="page"':''}>${image(i)}${label}</a>`).join('')}</nav>`);}
const regionName=()=>state.region==='moscow'?'Москва':state.region==='mo'?'Московская область':'Москва и область';
const opts=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
function renderFooter(){$('#footer').innerHTML=`<div class="footer-grid"><div>${brand()}<p>Ветеринарная помощь рядом.<br>Выбирайте с заботой о питомце.</p></div><div><strong>Найти помощь</strong><a href="#clinics">Клиники</a><a href="#doctors">Специалисты</a><a href="#services">Услуги и цены</a></div><div><strong>Для владельца</strong><a href="#favorites">Избранные клиники</a><a href="#about">Как записаться</a><a href="#about?section=sources">О сервисе и данных</a></div><div><strong>Без лишних шагов</strong><p>Сравните клиники и услуги без регистрации. Время приёма подтвердит выбранная клиника.</p><a href="#login" data-action="register">Создать аккаунт ${svg('arrow')}</a></div></div><div class="footer-bottom"><span>© 2026 Vetora · Интерактивный прототип</span><span>Сведения из открытых источников · Цены уточняйте в клинике</span></div>`;}
function sectionHead(title,link,label,description=''){return `<div class="section-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${link?`<a class="text-link" href="${link}">${label}${svg('arrow')}</a>`:''}</div>`;}
function clinicPrice(c){return c.services.find(s=>s.id===state.service)||c.services.find(s=>state.category!=='all'&&s.category===state.category)||c.services.find(s=>s.id==='therapy')||c.services[0];}
function clinicCard(c){const p=clinicPrice(c);return `<article class="clinic-card"><img class="clinic-photo" src="${esc(asset(c.image))}" alt="${esc(c.imgCredit.replace('Фото: ',''))}" loading="lazy"><div class="clinic-body"><div class="clinic-network">${esc(c.network)} · ${esc(c.city)}</div><h3><a href="${clinicHref(c)}">${esc(c.name)}</a></h3><div class="clinic-meta">${svg('pin')}<span>${esc(c.address.replace('Москва, ',''))}</span></div><div class="clinic-meta">${svg('clock')}<span>${esc(c.hours)}</span></div><div class="clinic-price">${state.service||state.category!=='all'?esc(p.title):'Первичный приём'} <strong>${money(p.price)}</strong></div><div class="clinic-actions"><a class="btn" href="${clinicHref(c)}">Подробнее ${svg('arrow')}</a><button class="favorite" data-action="favorite" data-id="${c.id}" aria-label="${favorites.has(c.id)?'Убрать из избранного':'Добавить в избранное'}: ${esc(c.name)}" aria-pressed="${favorites.has(c.id)}">${svg('heart')}</button></div></div></article>`;}
function clinicHref(c){const p=new URLSearchParams({clinic:c.id});for(const k of ['service','category','region'])if(state[k]&&state[k]!=='all')p.set(k,state[k]);return '#clinic?'+p;}
function publicClinics(){return clinics.filter(c=>state.region==='all'||(state.region==='mo'?c.area==='mo':c.area!=='mo'));}
function matchingClinics(){const q=normalize(state.q);return publicClinics().filter(c=>(state.area==='all'||c.area===state.area)&&(state.network==='all'||c.network===state.network)&&(state.category==='all'||c.services.some(s=>s.category===state.category))&&(!state.service||c.services.some(s=>s.id===state.service))&&(!q||normalize([c.name,c.address,c.location,...c.services.map(s=>s.title),...doctors.filter(d=>d.clinicId===c.id).map(d=>d.name)].join(' ')).includes(q))).sort((a,b)=>state.sort==='low'?clinicPrice(a).price-clinicPrice(b).price:state.sort==='name'?a.name.localeCompare(b.name,'ru'):0);}
function specialtyCards(){return categoryList.slice(0,6).map(([id,name,i])=>`<button class="specialty" data-action="specialists" data-category="${id}"><h3>${id==='therapy'?'Терапевт':id==='surgery'?'Хирург':id==='diagnostic'?'Врач УЗИ':id==='dental'?'Стоматолог':id==='dermatology'?'Дерматолог':'Кардиолог'}</h3><small>Выбрать специалиста</small>${image(i)}${svg('arrow','mini-arrow')}</button>`).join('');}
function featuredServices(){const selections=[['sd-kuzminki','therapy'],['sd-kuzminki','diagnostic-abdomen'],['sd-kuzminki','microchip'],['sd-kuzminki','vaccine-cat'],['sd-kuzminki','checkup-standard'],['bk-mitino','dental-consult']];return selections.map(([id,sid])=>{const original=clinics.find(c=>c.id===id);const c=publicClinics().find(c=>c.id===id)||publicClinics().find(c=>c.network===original.network&&c.services.some(s=>s.id===sid));if(!c)return '';const s=c.services.find(s=>s.id===sid);return `<button class="service" data-action="service" data-service="${s.id}" data-category="${s.category}"><span><strong>${esc(s.id==='diagnostic-abdomen'?'УЗИ брюшной полости':s.id==='vaccine-cat'?'Поливалентная вакцинация':s.title)}</strong><small>${esc(c.network)} · ${catName(s.category)}</small></span><span class="price-pill">от ${money(s.price)}</span></button>`;}).join('');}
function mapMarkup(large=false){const c=clinics.find(c=>c.id===state.mapClinic);const text=c?c.network+' '+c.address:'ветеринарные клиники '+regionName();const url='https://yandex.ru/map-widget/v1/?text='+encodeURIComponent(text)+'&z='+(c?'15':'11');return `<div class="map-wrap"><iframe title="Карта: ${esc(c?c.name:'ветеринарные клиники Москвы и области')}" src="${esc(url)}" loading="lazy" referrerpolicy="no-referrer" allowfullscreen></iframe><div class="map-caption"><strong>${c?esc(c.name):'Клиники на карте'}</strong><small>Яндекс Карты · Для загрузки нужен интернет</small></div></div><p class="source-note">${c?esc(c.address)+' · ':''}<a href="https://yandex.ru/maps/?text=${encodeURIComponent(text)}" target="_blank" rel="noopener noreferrer">Открыть в Яндекс Картах ↗</a> · Сведения на карте предоставляет картографический сервис.</p>`;}
function mapOptions(){return `<label><span class="sr-only">Клиника на карте</span><select id="map-select">${opts([['','Все клиники'],...publicClinics().map(c=>[c.id,c.name])],state.mapClinic)}</select></label>`;}
function pharmacyCards(){return [['Открытое шоссе, 5, корп. 6','Бульвар Рокоссовского'],['Нижняя Красносельская, 28','Красносельская'],['Егерская улица, 1','Сокольники']].map(([address,metro])=>`<a class="pharmacy" href="https://www.vetlek.ru/contacts/" target="_blank" rel="noopener noreferrer">${svg('plus')}<span><strong>Ветлек · ${metro}</strong><small>${address}</small></span>${svg('external','external')}</a>`).join('');}
function home(){const list=matchingClinics();return `<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow">Забота начинается с правильного выбора</div><h1 id="hero-title">Поиск по врачам и клиникам ${state.region==='mo'?'в Подмосковье':'в Москве'}</h1><p>Найдите клинику, врача или нужную услугу.<br>Сравните предложения и перейдите к записи без регистрации.</p></div>${image(3,'hero-art')}<form class="search" id="hero-search" role="search"><label class="field-shell">${svg('search')}<span class="sr-only">Клиника, услуга или врач</span><input type="search" name="q" id="hero-query" placeholder="Клиника, услуга или врач" autocomplete="off" value="${esc(state.q)}"></label><label class="field-shell"><span class="sr-only">Район или город</span><select id="hero-area" name="area">${opts(areas,state.area)}</select></label><button class="btn primary" type="submit">Найти</button></form></section>
<div class="quick-grid" aria-label="Быстрые действия"><a class="quick" href="#clinics"><span class="quick-icon">${image(4)}</span><span><strong>Найти запись</strong><small>Выбрать услугу и клинику</small></span></a><button class="quick" data-action="${state.demoSession?'account':'login'}"><span class="quick-icon">${image(2)}</span><span><strong>Мои клиники</strong><small>${state.demoSession?'Демонстрационный кабинет':'После входа в аккаунт'}</small></span></button><button class="quick" data-action="${state.demoSession?'account':'login'}"><span class="quick-icon">${image(4)}</span><span><strong>Карта питомца</strong><small>После входа в аккаунт</small></span></button><a class="quick" href="#favorites"><span class="quick-icon">${svg('heart')}</span><span><strong>Избранное</strong><small>Сохраняйте без входа</small></span></a></div>
<section class="section">${sectionHead('Популярные специалисты','#doctors','Все врачи')}<div class="specialty-grid">${specialtyCards()}</div></section>
<section class="section">${sectionHead('Популярные услуги','#services','Все услуги')}<div class="service-grid">${featuredServices()}</div><p class="source-note">Цены из официальных прайсов. Итоговая стоимость и состав услуги — в выбранной клинике.</p></section>
<section class="section"><div class="section-head clinic-section-head"><h2>Клиники Москвы и области</h2><div class="section-controls"><label><span class="sr-only">Направление в подборке клиник</span><select id="home-category">${opts([['all','Все направления'],...categoryList.filter(c=>['therapy','surgery','diagnostic','dental','vaccination'].includes(c[0]))],state.category)}</select></label><a class="btn" href="#clinics">Все клиники ${svg('arrow')}</a></div></div><div class="clinic-grid" id="home-clinics">${list.length?list.slice(0,state.homeLimit).map(clinicCard).join(''):empty('Нет клиник по выбранным условиям','Попробуйте другое направление или измените регион.')}</div>${list.length>state.homeLimit?`<div class="center"><button class="btn" data-action="more">Показать ещё ${list.length-state.homeLimit}</button></div>`:''}<p class="source-note">${publicClinics().length} реальных филиалов · Фотографии и адреса с сайтов клиник. Для «Своего Доктора» указан прайс сети; цену филиала подтвердит клиника.</p></section>
<section class="section"><div class="section-head"><h2>На карте</h2><div class="section-controls">${mapOptions()}<a class="btn" href="#map">Большая карта ${svg('external')}</a></div></div><div id="map-content">${mapMarkup()}</div></section>
<section class="section">${sectionHead('Направления','','')}<div class="directions">${categoryList.map(([id,name,i])=>`<button class="direction" data-action="direction" data-category="${id}">${image(i)}<span>${name}</span></button>`).join('')}</div></section>
<section class="section">${sectionHead('Ветаптеки','https://www.vetlek.ru/contacts/','Адреса и часы работы')}<div class="pharmacy-grid">${pharmacyCards()}</div></section>`;}
function breadcrumb(text){return `<nav class="breadcrumb" aria-label="Навигационная цепочка"><a href="#home">Главная</a><span aria-hidden="true">/</span><span aria-current="page">${esc(text)}</span></nav>`;}
function empty(title,body,button=true){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(body)}</p>${button?'<button class="btn" data-action="reset">Сбросить фильтры</button>':''}</div>`;}
function filters(kind='clinics'){return `<div class="filter-bar"><label class="sr-only" for="catalog-query">Поиск по ${kind==='doctors'?'специалистам':'клиникам'}</label><input id="catalog-query" type="search" placeholder="${kind==='doctors'?'Фамилия или специализация':'Название, адрес, врач или услуга'}" value="${esc(state.q)}" autocomplete="off"><label><span class="sr-only">Район или город</span><select id="filter-area">${opts(areas,state.area)}</select></label><label><span class="sr-only">Сеть клиник</span><select id="filter-network">${opts([['all','Все сети'],['Белый Клык','Белый Клык'],['Свой Доктор','Свой Доктор']],state.network)}</select></label><label><span class="sr-only">Сортировать</span><select id="filter-sort">${opts([['default','По умолчанию'],['low','Сначала дешевле'],['name','По названию']],state.sort)}</select></label></div>`;}
function chips(){return `<div class="chip-row" role="group" aria-label="Направление">${[['all','Все направления'],...categoryList.filter(c=>c[0]!=='all')].map(([id,name])=>`<button class="chip" data-action="category" data-category="${id}" aria-pressed="${state.category===id}">${name}</button>`).join('')}</div>`;}
function clinicListPage(){return `${breadcrumb('Клиники')}<div class="page-title"><div><h1>${state.service?esc(clinics.flatMap(c=>c.services).find(s=>s.id===state.service)?.title||'Выберите клинику'):'Выберите клинику'}</h1><p>Адреса, услуги и опубликованные цены. Запись — на официальном сайте клиники.</p></div></div>${filters()}${chips()}<div class="results-meta"><span id="result-count" role="status" aria-live="polite"></span><button class="btn ghost" data-action="reset">Сбросить фильтры</button></div><div class="clinic-grid" id="catalog-results"></div><p class="source-note">${priceNote()}</p>`;}
const priceNote=()=>`Тарифы сохранены из прайсов от 05.11.2026. Первичный приём сверён 08.11.2026. Расходные материалы и дополнительные исследования могут оплачиваться отдельно. <a href="https://bkvet.ru/prices/" target="_blank" rel="noopener noreferrer">Прайс «Белого Клыка» ↗</a> · <a href="https://www.svoydoctor.ru/vladeltsam/tseny/price-list/" target="_blank" rel="noopener noreferrer">Прайс «Своего Доктора» ↗</a>`;
function updateClinics(){const list=matchingClinics();$('#catalog-results').innerHTML=list.length?list.map(clinicCard).join(''):empty('Ничего не нашлось','Попробуйте изменить запрос, направление или регион.');$('#result-count').textContent='Найдено клиник: '+list.length;}
function servicesPage(){const map=new Map();for(const c of publicClinics())for(const s of c.services){const key=c.network+'|'+s.id;if(!map.has(key))map.set(key,{...s,network:c.network,url:c.priceUrl});}const list=[...map.values()].filter(s=>(state.category==='all'||s.category===state.category)&&(!state.q||normalize(s.title+' '+catName(s.category)).includes(normalize(state.q))));return `${breadcrumb('Услуги')}<div class="page-title"><div><h1>Услуги для питомцев</h1><p>Выберите услугу и сравните предложения клиник.</p></div></div><label class="field-shell">${svg('search')}<span class="sr-only">Найти услугу</span><input id="service-query" type="search" placeholder="Например, УЗИ или вакцинация" value="${esc(state.q)}"></label>${chips()}<div class="results-meta"><span role="status">Предложений в подборке: ${list.length}</span><button class="btn ghost" data-action="reset">Сбросить фильтры</button></div><div class="service-grid">${list.length?list.map(s=>`<button class="service" data-action="service" data-service="${s.id}" data-category="${s.category}" data-network="${esc(s.network)}"><span><strong>${esc(s.title)}</strong><small>${esc(s.network)}</small></span><span class="price-pill">${money(s.price)}</span></button>`).join(''):empty('Такой услуги в подборке пока нет','На официальных сайтах клиник доступны другие направления и полный перечень услуг.',false)}</div>${!list.length?'<div class="center"><a class="btn" href="https://www.svoydoctor.ru/vladeltsam/uslugi/" target="_blank" rel="noopener noreferrer">Все услуги клиники ↗</a></div>':''}<p class="source-note">${priceNote()}</p>`;}
function doctorCard(d){return `<article class="doctor-card"><img src="${esc(asset(d.image))}" alt="${esc(d.name)}" loading="lazy"><h2>${esc(d.name)}</h2><p>${esc(d.title)}</p><p>Свой Доктор · Кузьминки<br>Жигулёвская улица, 6, корпус 2</p><button class="btn" data-action="doctor" data-id="${d.id}">О специалисте ${svg('arrow')}</button></article>`;}
function matchingDoctors(){return doctors.filter(d=>(state.region!=='mo')&&(state.category==='all'||d.categories.includes(state.category))&&(!state.q||normalize(d.name+' '+d.title+' '+d.categories.map(catName).join(' ')).includes(normalize(state.q))));}
function doctorsPage(){const list=matchingDoctors();return `${breadcrumb('Врачи')}<div class="page-title"><div><h1>Найдите своего специалиста</h1><p>Профили и фотографии — с официального сайта клиники.</p></div></div><label class="field-shell">${svg('search')}<span class="sr-only">Фамилия или специализация врача</span><input id="doctor-query" type="search" placeholder="Фамилия или специализация" value="${esc(state.q)}"></label>${chips()}<div class="results-meta"><span role="status">В подборке: ${list.length}</span><button class="btn ghost" data-action="reset">Сбросить фильтры</button></div><div class="doctor-grid">${list.length?list.map(doctorCard).join(''):empty('Профили для этого направления ещё не добавлены','Посмотрите специалистов в официальном каталоге сети или выберите другое направление.',false)}</div><div class="info-panel">Это небольшая подборка проверенных профилей. <a href="https://www.svoydoctor.ru/vladeltsam/spetsialisty/" target="_blank" rel="noopener noreferrer">Все специалисты «Своего Доктора» ↗</a> · <a href="https://bkvet.ru/doctors/" target="_blank" rel="noopener noreferrer">Все специалисты «Белого Клыка» ↗</a></div>`;}
function clinicDetail(){const c=clinics.find(c=>c.id===state.clinic);if(!c)return `${breadcrumb('Клиника не найдена')}${empty('Клиника не найдена','Откройте каталог и выберите клинику.',false)}<div class="center"><a class="btn" href="#clinics">К клиникам</a></div>`;const services=c.services.filter(s=>(!state.service||s.id===state.service)&&(state.category==='all'||s.category===state.category));return `${breadcrumb(c.name)}<section class="detail-top"><img src="${esc(asset(c.image))}" alt="${esc(c.imgCredit.replace('Фото: ',''))}"><div class="detail-copy"><div class="eyebrow">${esc(c.network)} · ${esc(c.city)}</div><h1>${esc(c.name)}</h1><p>${esc(c.address)}</p><p>${esc(c.hours)}</p><div class="detail-meta"><a href="tel:${c.phone.replace(/[^+\d]/g,'')}">${esc(c.phone)}</a><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Сайт клиники ${svg('external')}</a><a href="https://yandex.ru/maps/?text=${encodeURIComponent(c.address+' '+c.network)}" target="_blank" rel="noopener noreferrer">На карте ${svg('pin')}</a></div><button class="btn primary" data-action="book" data-id="${c.id}" data-service="${esc(state.service)}">Записаться без входа ${svg('arrow')}</button></div></section><section class="section">${sectionHead('Услуги и цены',c.priceUrl,'Официальный прайс')}<div class="detail-services">${(services.length?services:c.services).map(s=>`<article class="detail-service"><div><h3>${esc(s.title)}</h3><p>${esc(s.detail)}</p></div><div><span>${money(s.price)}</span><button class="btn" data-action="book" data-id="${c.id}" data-service="${s.id}">Выбрать</button></div></article>`).join('')}</div><p class="source-note">${priceNote()} ${c.priceScope==='network'?'Указан прайс сети; доступность услуги и цену этого филиала подтвердит клиника.':''}</p></section>${doctors.some(d=>d.clinicId===c.id)?`<section class="section">${sectionHead('Специалисты клиники','#doctors','Все врачи')}<div class="doctor-grid">${doctors.filter(d=>d.clinicId===c.id).map(doctorCard).join('')}</div></section>`:''}`;}
function favoritesPage(){const list=clinics.filter(c=>favorites.has(c.id));return `${breadcrumb('Избранное')}<div class="page-title"><div><h1>Ваши избранные клиники</h1><p>Сохранены в этом браузере. Регистрация не требуется.</p></div></div><div class="clinic-grid">${list.length?list.map(clinicCard).join(''):empty('Сохраните клинику на потом','Нажмите на сердечко в карточке клиники. Она появится здесь.',false)}</div>${!list.length?'<div class="center"><a class="btn primary" href="#clinics">Выбрать клинику</a></div>':''}`;}
function mapPage(){return `${breadcrumb('Карта')}<div class="page-title"><div><h1>Клиники на карте</h1><p>Выберите филиал, чтобы увидеть адрес и построить маршрут.</p></div></div><div class="section-head"><a class="text-link" href="#clinics">${svg('arrow')} К списку клиник</a><div class="section-controls">${mapOptions()}</div></div><div class="map-large" id="map-content">${mapMarkup(true)}</div>`;}
function about(){return `${breadcrumb('О сервисе')}<div class="page-title"><h1>Забота без лишних шагов</h1></div><div class="about-copy"><h2>Как записаться</h2><p>1. Найдите специалиста, услугу или клинику.</p><p>2. Посмотрите адрес, опубликованные цены и информацию о враче.</p><p>3. Нажмите «Записаться без входа». Мы покажем ваш выбор и ссылку на официальный сайт клиники, где можно согласовать время и завершить запись.</p><p>Регистрация в Vetora не требуется. Сайт клиники может попросить ваши контактные данные. Выбор на этой странице ещё не бронирует время.</p><h2>Откуда сведения</h2><p>Клиники, фотографии и тарифы — из официальных источников <a href="https://bkvet.ru/contacts/" target="_blank" rel="noopener noreferrer">«Белого Клыка»</a> и <a href="https://www.svoydoctor.ru/vladeltsam/filialy/" target="_blank" rel="noopener noreferrer">«Своего Доктора»</a>. Контакты проверены 08.11.2026; даты тарифов указаны рядом с ценами. Профили врачей проверены 08.11.2026.</p><p>Порядок карточек редакционный. В сервисе пока нет рейтингов или статистики популярности.</p><h2>Вход и регистрация</h2><p>Это интерактивный HTML-прототип. Вход и регистрация демонстрационные: без отправки SMS, создания реального аккаунта и сохранения ваших персональных данных.</p><button class="btn primary" data-action="register">Посмотреть регистрацию</button></div>`;}
function render(){renderHeader();renderFooter();$('#main').innerHTML=({home,clinics:clinicListPage,services:servicesPage,doctors:doctorsPage,clinic:clinicDetail,favorites:favoritesPage,map:mapPage,about}[state.page]||home)();if(state.page==='clinics')updateClinics();document.title='Vetora — '+({home:'ветеринарная помощь рядом',clinics:'выбрать клинику',services:'услуги и цены',doctors:'специалисты',clinic:clinics.find(c=>c.id===state.clinic)?.name||'клиника',favorites:'избранное',map:'клиники на карте',about:'как записаться'}[state.page]);}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function openDialog(html){const d=$('#dialog');if(!d.open)trigger=document.activeElement;d.innerHTML=html;document.body.classList.add('modal-open');if(!d.open)d.showModal();setTimeout(()=>{const f=d.querySelector('[autofocus]')||d.querySelector('.close');f?.focus();},0);}
function closeDialog(){const d=$('#dialog');d.close();document.body.classList.remove('modal-open');if(trigger?.isConnected)trigger.focus({preventScroll:true});else $('#main').focus({preventScroll:true});trigger=null;}
const dialogHead=title=>`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="Закрыть окно">${svg('close')}</button></div>`;
function regionDialog(){openDialog(`<div class="dialog-content">${dialogHead('Где искать помощь?')}<p>Покажем клиники выбранного региона.</p><div class="region-options">${[['all','Москва и область'],['moscow','Москва'],['mo','Московская область']].map(([id,label])=>`<button class="btn white" data-action="set-region" data-region="${id}" ${state.region===id?'aria-current="true"':''}>${label}${state.region===id?svg('check'):svg('arrow')}</button>`).join('')}</div></div>`);}
function auth(mode='login'){openDialog(`<div class="auth-visual"><img src="assets/auth-pets-generated.png" alt="">${brand()}</div><div class="dialog-content">${dialogHead(mode==='register'?'Зарегистрироваться':'Рады вас видеть')}<p>${mode==='register'?'Питомцы, клиники и записи — в одном месте.':'Войдите, чтобы видеть своих питомцев и записи.'}</p><div class="info-panel">Демонстрационный вход: SMS не отправляется, реальный аккаунт не создаётся. Не используйте настоящие персональные данные.</div><form id="auth-form" data-mode="${mode}" novalidate>${mode==='register'?'<label for="auth-name">Как к вам обращаться</label><input id="auth-name" name="name" autocomplete="off" maxlength="60" placeholder="Например, Анна">':''}<label for="auth-phone">Номер телефона</label><input id="auth-phone" name="phone" type="tel" inputmode="tel" autocomplete="off" placeholder="+7 (999) 123-45-67" aria-describedby="auth-error" autofocus required><div class="error" id="auth-error" role="alert"></div>${mode==='register'?'<div class="checkbox-row"><input id="auth-consent" type="checkbox" required><label for="auth-consent">Я понимаю, что это демонстрация и реальный аккаунт создан не будет.</label></div>':''}<button class="btn primary wide" type="submit">Продолжить в прототипе ${svg('arrow')}</button></form><button class="dialog-switch" data-action="${mode==='register'?'login':'register'}">${mode==='register'?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'}</button></div>`);}
function demoCode(mode){$('#dialog').innerHTML=`<div class="dialog-content">${dialogHead('Проверка кода')}<p>В настоящем сервисе здесь будет проверка номера. В прототипе введите демонстрационный код <strong>000000</strong>.</p><form id="code-form" data-mode="${mode}" novalidate><label for="auth-code">Демонстрационный код</label><input id="auth-code" type="text" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" placeholder="000000" aria-describedby="code-error" required><div id="code-error" class="error" role="alert"></div><button class="btn primary wide" type="submit">${mode==='register'?'Завершить демонстрацию регистрации':'Войти в деморежим'}</button></form><button class="dialog-switch" data-action="${mode==='register'?'register':'login'}">Вернуться к номеру</button></div>`;$('#auth-code').focus();}
function account(){openDialog(`<div class="dialog-content">${dialogHead('Демонстрационный кабинет')}<p>Вход в прототип выполнен. Реального аккаунта, питомцев и записей пока нет.</p><div class="info-panel">Для рабочего личного кабинета требуется подключить серверную авторизацию и данные владельца.</div><button class="btn primary wide" data-action="browse">Найти клинику</button><button class="dialog-switch" data-action="logout">Выйти из деморежима</button></div>`);}
function doctorDialog(id){const d=doctors.find(d=>d.id===id);if(!d)return;openDialog(`<div class="dialog-content">${dialogHead(esc(d.name))}<img src="${esc(asset(d.image))}" alt="${esc(d.name)}" style="width:88px;height:88px;border-radius:50%;object-fit:cover;object-position:top;margin:14px 0"><p>${esc(d.title)}<br>Свой Доктор · Кузьминки</p><p>Адрес: Жигулёвская улица, 6, корпус 2.</p><a class="text-link" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Профиль на сайте клиники ${svg('external')}</a><div class="info-panel">Расписание и стоимость приёма этого специалиста уточняются в клинике.</div><button class="btn primary wide" data-action="book" data-id="${d.clinicId}" data-doctor="${d.id}">Перейти к записи без входа ${svg('arrow')}</button></div>`);}
function book(id,serviceId='',doctorId=''){const c=clinics.find(c=>c.id===id);if(!c)return;const doc=doctors.find(d=>d.id===doctorId&&d.clinicId===id);const service=c.services.find(s=>s.id===serviceId);openDialog(`<div class="dialog-content">${dialogHead('Запись в клинику')}<p>Выбрали клинику — осталось согласовать удобное время.</p><div class="summary-row"><span>Клиника</span><strong>${esc(c.name)}</strong></div><div class="summary-row"><span>Адрес</span><strong>${esc(c.address)}</strong></div>${doc?`<div class="summary-row"><span>Специалист</span><strong>${esc(doc.name)}</strong></div>`:''}${service?`<div class="summary-row"><span>Услуга</span><strong>${esc(service.title)}</strong></div><div class="summary-row"><span>Цена из прайса${c.priceScope==='network'?' сети':''}</span><strong>${money(service.price)}</strong></div>`:!doc?`<label for="booking-service">Выберите услугу</label><select id="booking-service" data-clinic="${c.id}"><option value="">Уточню в клинике</option>${c.services.map(s=>`<option value="${s.id}">${esc(s.title)} · ${money(s.price)}</option>`).join('')}</select>`:''}<div class="info-panel">Завершите запись на официальном сайте клиники. Время и окончательную стоимость подтвердит клиника. Ваш выбор автоматически не передаётся — назовите услугу или врача при записи.</div><a class="btn primary wide" id="provider-link" href="${esc(doc?doc.url:c.network==='Белый Клык'?'https://bkvet.ru/appointment/':c.url)}" target="_blank" rel="noopener noreferrer">Записаться на сайте клиники ${svg('external')}</a><a class="btn white wide" href="tel:${c.phone.replace(/[^+\d]/g,'')}">Позвонить ${esc(c.phone)}</a><p class="small muted" style="margin:14px 0 0">Вход в Vetora не нужен. Запись ещё не создана.</p></div>`);}
function reset(){route(state.page==='home'?'home':state.page,{q:'',category:'all',area:'all',network:'all',sort:'default',service:''});}
function updateQuery(value,inputId){state.q=value;if(state.page==='clinics'){updateClinics();}else{const input=$('#'+inputId),pos=input.selectionStart;$('#main').innerHTML=state.page==='services'?servicesPage():doctorsPage();const next=$('#'+inputId);next.focus();next.setSelectionRange(pos,pos);}const p=new URLSearchParams(location.hash.split('?')[1]||'');if(value)p.set('q',value);else p.delete('q');history.replaceState(null,'','#'+state.page+(p.size?'?'+p:''));}
document.addEventListener('click',e=>{const skip=e.target.closest('.skip');if(skip){e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView();return;}const link=e.target.closest('a[href^="#"]:not([data-action])');if(link){const href=link.getAttribute('href');if(/^#(home|clinics|doctors|services|favorites|map|about|clinic)(?:\?|$)/.test(href)&&state.region!=='all'&&!new URLSearchParams(href.split('?')[1]||'').has('region')){e.preventDefault();location.hash=href+(href.includes('?')?'&':'?')+'region='+encodeURIComponent(state.region);return;}}const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();const {action,id,category,service,network,doctor,region}=button.dataset;
 if(action==='close')closeDialog();else if(action==='region')regionDialog();else if(action==='set-region'){closeDialog();state.homeLimit=6;state.mapClinic='';route(state.page,{region,area:'all',q:'',network:'all',category:'all',service:''});}
 else if(action==='login'||action==='register')auth(action);else if(action==='account')account();else if(action==='logout'){state.demoSession=false;closeDialog();renderHeader();toast('Вы вышли из деморежима');}else if(action==='browse'){closeDialog();route('clinics',{q:'',category:'all',service:''});}
 else if(action==='favorite'){if(favorites.has(id))favorites.delete(id);else favorites.add(id);try{localStorage.setItem('vetora-v2-favorites',JSON.stringify([...favorites]));}catch{}const saved=favorites.has(id);button.setAttribute('aria-pressed',String(saved));button.setAttribute('aria-label',(saved?'Убрать из избранного: ':'Добавить в избранное: ')+clinics.find(c=>c.id===id)?.name);toast(saved?'Клиника добавлена в избранное':'Клиника удалена из избранного');if(state.page==='favorites'){$('#main').innerHTML=favoritesPage();$('#main').focus({preventScroll:true});}}
 else if(action==='more'){state.homeLimit=clinics.length;const top=window.scrollY;$('#main').innerHTML=home();window.scrollTo(0,top);const cards=$$('#home-clinics .clinic-card');cards[6]?.querySelector('a')?.focus({preventScroll:true});}
 else if(action==='specialists')route('doctors',{category,q:'',service:'',network:'all',area:'all'});
 else if(action==='direction')route(['dermatology','cardiology','ophthalmology','neurology','oncology','orthopedics'].includes(category)?'doctors':'services',{category,q:'',service:'',network:'all'});
 else if(action==='category')route(state.page,{category,service:'',network:'all'});
 else if(action==='service')route('clinics',{service,category,q:'',network:network||'all',area:'all'});
 else if(action==='reset')reset();else if(action==='doctor')doctorDialog(id);else if(action==='book')book(id,service,doctor);
});
document.addEventListener('submit',e=>{const form=e.target;if(form.id==='hero-search'){e.preventDefault();route('clinics',{q:$('#hero-query').value.trim(),area:$('#hero-area').value,category:'all',service:'',network:'all'});}else if(form.id==='auth-form'){e.preventDefault();const input=$('#auth-phone'),digits=input.value.replace(/\D/g,'');const valid=/^[78]\d{10}$/.test(digits);if(!valid){$('#auth-error').textContent='Введите номер в формате +7 (999) 123-45-67.';input.setAttribute('aria-invalid','true');input.focus();return;}if(form.dataset.mode==='register'&&!$('#auth-consent').checked){$('#auth-error').textContent='Подтвердите, что понимаете демонстрационный режим.';$('#auth-consent').focus();return;}demoCode(form.dataset.mode);}else if(form.id==='code-form'){e.preventDefault();if($('#auth-code').value!=='000000'){$('#code-error').textContent='В прототипе используйте код 000000.';$('#auth-code').setAttribute('aria-invalid','true');$('#auth-code').focus();return;}state.demoSession=true;closeDialog();renderHeader();toast(form.dataset.mode==='register'?'Демонстрация регистрации завершена':'Вы вошли в деморежим');account();}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-query'||e.target.id==='service-query'||e.target.id==='doctor-query')updateQuery(e.target.value,e.target.id);if(e.target.id==='auth-phone'){e.target.removeAttribute('aria-invalid');$('#auth-error').textContent='';}if(e.target.id==='auth-code'){e.target.removeAttribute('aria-invalid');$('#code-error').textContent='';}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='home-category'){focusAfterRoute=id;state.homeLimit=6;route('home',{category:e.target.value,q:'',service:'',area:'all',network:'all'});}else if(id==='filter-area'||id==='filter-network'||id==='filter-sort'){focusAfterRoute=id;const key={'filter-area':'area','filter-network':'network','filter-sort':'sort'}[id];route(state.page,{[key]:e.target.value});}else if(id==='map-select'){state.mapClinic=e.target.value;$('#map-content').innerHTML=mapMarkup(state.page==='map');}else if(id==='booking-service'){book(e.target.dataset.clinic,e.target.value);}});
$('#dialog').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const controls=$$('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex="0"]',$('#dialog')).filter(el=>el.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(!first){e.preventDefault();return;}if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
// Links inside a modal should close it before hash navigation.
$('#dialog').addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))closeDialog();});
window.addEventListener('hashchange',readRoute);readRoute();
window.VETORA_ITERATION={version:2,mode:'standalone public prototype',clinics:clinics.length,doctors:doctors.length,getState:()=>({...state,favorites:[...favorites]}),navigate:route};
})();
